P7Stream_FCD0F7:
	.byte	0x00, 0x05   ; 0xFCD0F7  op  0  len 5  payload 3
	.byte	0x6e, 0xee, 0xef   ; 0xFCD0F9
	.byte	0xf0, 0x00   ; 0xFCD0FC  op 15  END

